head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _2 : Body 가 MultiLine 일때의 oneditkeydown 전용 분리 샘플.
//     한 데이터 레코드(rowIndex N)를 2개의 Line(TR)으로 표시(MultiLine).
//       Line1 : c1 | c2 | c3   (colIndex 0,1,2)
//       Line2 : c4 | c5 | c6   (colIndex 3,4,5)
//     · 본 샘플의 검증 2건은 embeddedInput 값과 무관하게 동일한 결과가 나오므로(3값 전수 실측)
//       기본값은 미설정으로 두고 con_embeddedInput 은 결과 동일성 확인용 보조 옵션으로만 둔다.
//       - 미설정/false : Cell 을 더블클릭해 편집 상태로 만든 뒤 키 입력
//       - true        : Cell 안 상시 입력창을 클릭한 뒤 바로 키 입력
//     · 같은 레코드의 Line1 Cell / Line2 Cell 에서 각각 키 입력 -> info.rowIndex 동일(레코드 단위 0~2)
//     · Line1/Line2 를 통틀어 모든 Column 은 0~5 로 연속된 고유 info.colIndex 를 가짐
//     그 외 항목은 _1 샘플에서 다루므로 본 샘플에서는 제외.
scwin.tData = {
    "description" : "[gridView > E > oneditkeydown]<br/>Body Cell 의 편집 영역에서 키보드의 키를 누를때 발생합니다.",
    "validation" : [
        "Body 가 MultiLine 일때 각 Line 의 Row 인덱스값은 같습니다.",
        "Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값(코드값 "1" = 미설정) 명시 설정
    con_embeddedInput.setValue("1");

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — MultiLine(레코드당 2 Line), 셀별 고유값.
//   레코드 | Line1(c1,c2,c3) | Line2(c4,c5,c6)
//   ------+-----------------+-----------------
//    0    | A0 , B0 , C0    | D0 , E0 , F0
//    1    | A1 , B1 , C1    | D1 , E1 , F1
//    2    | A2 , B2 , C2    | D2 , E2 , F2
scwin.MLINE_DATA = [
    { "c1" : "A0", "c2" : "B0", "c3" : "C0", "c4" : "D0", "c5" : "E0", "c6" : "F0" },
    { "c1" : "A1", "c2" : "B1", "c3" : "C1", "c4" : "D1", "c5" : "E1", "c6" : "F1" },
    { "c1" : "A2", "c2" : "B2", "c3" : "C2", "c4" : "D2", "c5" : "E2", "c6" : "F2" }
];



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - MultiLine(레코드당 2 Line) 그리드 1개를 동적 생성.
//      Line1=c1,c2,c3 (colIndex 0,1,2) / Line2=c4,c5,c6 (colIndex 3,4,5)
//  - Body Column 의 embeddedInput 은 con_embeddedInput (미설정/true/false) 선택값으로 적용한다.
//    (미설정이면 embeddedInput 속성 자체를 넣지 않는다. con 은 렌더 시 결정되므로 [Target 재생성] 으로만 반영)
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // con_embeddedInput 적용값 (gdl_boolean 바인딩이므로 getText() 로 라벨(''/true/false) 을 읽는다)
    //  · 미설정('') 이면 embeddedInput 속성 자체를 넣지 않는다.
    let embeddedInput = con_embeddedInput.getText();
    let strEmbedded = (embeddedInput === '') ? '' : ' embeddedInput="' + embeddedInput + '"';

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  · createLabel 문자 제약 : 작은따옴표 금지, 줄바꿈은 개행문자 사용
    $c.gcm.createLabel('label="[전제] MultiLine 구성 - 레코드 1건이 2줄로 표시됩니다. 1줄=c1·c2·c3, 2줄=c4·c5·c6 (레코드 3건)\n[전제] 아래 확인 항목은 embeddedInput 값과 무관하게 결과가 같으므로 con_embeddedInput 은 기본값인 미설정 상태 그대로 두고 확인합니다. 현재 적용값 : ' + (embeddedInput === '' ? '미설정' : embeddedInput) + '\n[절차] 미설정(또는 false) 상태에서는 Cell 을 더블클릭해 편집 상태로 만든 뒤 문자키를 누릅니다.\n[절차] 같은 레코드의 1줄 Cell 에서 문자키를 누르고, 이어서 같은 레코드 2줄 Cell 에서도 문자키를 누릅니다. 그 다음 1줄~2줄의 모든 Cell 에서 왼쪽부터 차례로 문자키를 눌러봅니다.\n[확인] 같은 레코드면 1줄/2줄 어느 Cell 에서 입력해도 rowIndex 가 같은지, 1줄과 2줄 Column 을 합쳐 colIndex 가 0부터 5까지 겹치지 않고 나오는지 결과창에서 확인\n[참고] con_embeddedInput 을 true 로 바꾸고 [Target 재생성] 버튼을 누르면 Cell 안에 상시 입력창이 표시되며, 이때는 그 입력창을 클릭한 뒤 문자키를 누릅니다. 어느 값이든 위 확인 결과가 같은지 보조로 확인할 수 있습니다."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성 (6개 컬럼 → createDynamicDataList(4컬럼 한계) 대신 인라인 생성)
    //  ★ DataList 컬럼 id 와 gBody 컬럼 id/dataList 를 모두 c1~c6 로 동일하게 (id 와 dataList 불일치 시 셀 빈값)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="c1" name="c1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="c2" name="c2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="c3" name="c3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="c4" name="c4" dataType="text"></w2:column>';
    strDlt += '<w2:column id="c5" name="c5" dataType="text"></w2:column>';
    strDlt += '<w2:column id="c6" name="c6" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.MLINE_DATA, false);

    // target 그리드 직접 구성 (MultiLine : header/gBody 각 <w2:row> 2개)
    //  · 3레코드 x 2Line x 30px + Header 2Line + caption 이 모두 보이도록 height 를 충분히 확보
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" editable="true" checkAllType="false" defaultCellHeight="30" ev:oneditkeydown="scwin.target1_oneditkeydown" id="" style="width:300px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="oneditkeydown MultiLine sample"></w2:caption>';
    // Header : Line1(c1,c2,c3) / Line2(c4,c5,c6)
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="hcol_c1" value="c1(idx0)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="hcol_c2" value="c2(idx1)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="hcol_c3" value="c3(idx2)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="hcol_c4" value="c4(idx3)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="hcol_c5" value="c5(idx4)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="hcol_c6" value="c6(idx5)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    // gBody : Line1(c1,c2,c3) / Line2(c4,c5,c6) → 레코드당 2 TR Line
    //  · embeddedInput 은 con_embeddedInput 선택값(strEmbedded)으로 적용 (미설정이면 속성 없음)
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="90" style="" inputType="text"' + strEmbedded + ' id="c1" dataList="c1"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text"' + strEmbedded + ' id="c2" dataList="c2"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text"' + strEmbedded + ' id="c3" dataList="c3"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="90" style="" inputType="text"' + strEmbedded + ' id="c4" dataList="c4"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text"' + strEmbedded + ' id="c5" dataList="c5"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text"' + strEmbedded + ' id="c6" dataList="c6"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// oneditkeydown : Body Cell 의 편집 영역에서 키를 누를때 발생.
//  ▶ 한 줄 + MultiLine 검증에 필요한 rowIndex / colIndex 만 출력
//   · MultiLine 이어도 같은 레코드의 1줄/2줄 Cell 은 info.rowIndex 동일
//   · info.colIndex(0~5) 는 Line 과 무관하게 모든 Column 이 고유
scwin.target1_oneditkeydown = function (info) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("▶ oneditkeydown");
    bottom.setReturnValue("info.rowIndex : " + info.rowIndex);
    bottom.setReturnValue("info.colIndex : " + info.colIndex);
}
